When mapping object keys (such as question IDs and paper IDs) for validation or lookup, explicitly reject null, empty, non-string, and duplicate keys to prevent silent validation bypasses.

```python
def source_maps() -> tuple[dict[str, Any], dict[str, Any]]:
    render = load_json(PREDECESSOR_RENDER_MANIFEST)
    questions = {}
    for row in render["questions"]:
        qid = row.get("question_id")
        if not isinstance(qid, str) or not qid.strip():
            raise ValueError(f"invalid_question_id:{qid}")
        if qid in questions:
            raise ValueError(f"duplicate_question_id:{qid}")
        questions[qid] = row
    papers = {}
    for row in render["papers"]:
        pid = row.get("paper_id")
        if not isinstance(pid, str) or not pid.strip():
            raise ValueError(f"invalid_paper_id:{pid}")
        if pid in papers:
            raise ValueError(f"duplicate_paper_id:{pid}")
        papers[pid] = row
    return questions, papers
```

